INSERT INTO `oc_modification` (`modification_id`, `name`, `code`, `author`, `version`, `link`, `xml`, `status`, `date_added`) VALUES
(1, 'GeoIP', 'GeoIP OC-2 5.3', 'Roman Shipilov', '5.3', 'http://opencart.progroman.ru/demo/1/', '<?xml version=\"1.0\" encoding=\"utf-8\"?>\r\n<modification>\r\n    <code>GeoIP OC-2 5.3</code>\r\n    <name>GeoIP</name>\r\n    <version>5.3</version>\r\n    <author>Roman Shipilov</author>\r\n    <link>http://opencart.progroman.ru/demo/1/</link>\r\n\r\n    <!-- Подключение модуля -->\r\n    <file path=\"catalog/controller/common/header.php\">\r\n        <operation>\r\n            <search><![CDATA[$data[\'language\'] = $this->load->controller(\'common/language\');]]></search>\r\n            <add position=\"before\"><![CDATA[		$data[\'geoip\'] = $this->load->controller(\'module/geoip\');]]></add>\r\n        </operation>\r\n    </file>\r\n\r\n    <!-- Подключение css и js -->\r\n    <file path=\"catalog/view/theme/*/template/common/header.tpl\">\r\n        <operation>\r\n            <search><![CDATA[<?php foreach ($styles as $style) { ?>]]></search>\r\n            <add position=\"before\"><![CDATA[<link href=\"catalog/view/theme/default/stylesheet/geoip.css\" rel=\"stylesheet\">]]></add>\r\n        </operation>\r\n        <operation>\r\n            <search><![CDATA[</head>]]></search>\r\n            <add position=\"before\">\r\n                <![CDATA[<script src=\"catalog/view/javascript/jquery/jquery.geoip-module.js\" type=\"text/javascript\"></script>]]></add>\r\n        </operation>\r\n    </file>\r\n\r\n    <!-- Добавляем вывод города на странице регистрации -->\r\n    <file path=\"catalog/controller/account/register.php\">\r\n        <operation>\r\n            <search>\r\n                <![CDATA[$data[\'city\'] = $this->request->post[\'city\'];]]>\r\n            </search>\r\n            <add position=\"after\">\r\n                <![CDATA[		} elseif (isset($this->session->data[\'shipping_address\'][\'city\'])) {\r\n            $data[\'city\'] = $this->session->data[\'shipping_address\'][\'city\'];]]>\r\n            </add>\r\n        </operation>\r\n    </file>\r\n\r\n    <!-- Добавляем вывод города при оформлении заказа с регистрацией -->\r\n    <file path=\"catalog/controller/checkout/register.php,catalog/controller/checkout/payment_address.php,catalog/controller/checkout/shipping_address.php\">\r\n        <operation>\r\n            <search index=\"0\">\r\n                <![CDATA[$this->load->model(\'localisation/country\');]]>\r\n            </search>\r\n            <add position=\"before\">\r\n                <![CDATA[\r\n        if (isset($this->session->data[\'shipping_address\'][\'city\'])) {\r\n            $data[\'city\'] = $this->session->data[\'shipping_address\'][\'city\'];\r\n        } else {\r\n            $data[\'city\'] = \'\';\r\n        }\r\n        ]]>\r\n            </add>\r\n        </operation>\r\n    </file>\r\n    <file path=\"catalog/view/theme/*/template/checkout/register.tpl,catalog/view/theme/*/template/checkout/payment_address.tpl,catalog/view/theme/*/template/checkout/shipping_address.tpl\">\r\n        <operation>\r\n            <search>\r\n                <![CDATA[<input type=\"text\" name=\"city\" value=\"\"]]>\r\n            </search>\r\n            <add position=\"replace\">\r\n                <![CDATA[<input type=\"text\" name=\"city\" value=\"<?php echo $city; ?>\"]]>\r\n            </add>\r\n        </operation>\r\n    </file>\r\n\r\n    <!-- SimpleGeo -->\r\n    <file path=\"catalog/model/tool/simplegeo.php\">\r\n        <operation>\r\n            <search>\r\n                <![CDATA[if ($mode == self::SIMPLE_GEO_OWN)]]>\r\n            </search>\r\n            <add position=\"before\">\r\n                <![CDATA[\r\n            $geoip = $this->registry->get(\'geoip\');\r\n            if ($geoip->getZoneId()) {\r\n	            ModelToolSimpleGeo::$geo = $geoip->getFullInfo();\r\n            } else]]>\r\n            </add>\r\n        </operation>\r\n    </file>\r\n\r\n</modification>', 1, '2018-11-05 20:00:36');
